{
    "levels": [
        {
            "title": "The NumPy Array - From Python Lists to N-Dimensional Data Structures",
            "description": "Understand the fundamental `ndarray`, the conceptual model for PyTorch tensors. Learn its defining properties (shape, dtype, ndim) and how its fixed-type, contiguous memory layout enables high-performance numerical computing, in stark contrast to Python lists."
